import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"尺寸图：毫米英寸换算与准确标注","description":"","frontmatter":{"id":"P18","title":"尺寸图：毫米英寸换算与准确标注","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":118},"headers":[],"relativePath":"prompts/P18.md","filePath":"prompts/P18.md"}'),l={name:"prompts/P18.md"};function t(i,s,c,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p18-尺寸图-毫米英寸换算与准确标注" tabindex="-1">P18 尺寸图：毫米英寸换算与准确标注 <a class="header-anchor" href="#p18-尺寸图-毫米英寸换算与准确标注" aria-label="Permalink to &quot;P18 尺寸图：毫米英寸换算与准确标注&quot;">​</a></h1><p>类型：计算＋图像规划。替换项目：真实测量记录、尺寸定义、舍入位数与实拍。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="/ai-visual-creation-handbook/ecommerce/localization">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请根据尺寸记录制作外尺寸图的文案与排版计划，本次先完成计算和标注，不猜结构。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数据：外部长L=220 mm、宽W=150 mm、高H=120 mm；没有内尺寸、容积和公差记录。</span></span>
<span class="line"><span>按1 in = 25.4 mm换算，保留原值和公式；英寸标注保留两位小数并写approx.或“约”。</span></span>
<span class="line"><span>输出应核算为：L约8.66 in、W约5.91 in、H约4.72 in；请逐项计算，而不是照抄结果。</span></span>
<span class="line"><span>制作时以实拍为底，箭头和尺寸文字单独可编辑；选能读懂长宽高的角度，不生成未提供的背面或内部图。</span></span>
<span class="line"><span>如果透视难以标示三轴，允许拆成两张已有角度图，不用拉伸商品凑图。</span></span>
<span class="line"><span>最终输出：计算表、单位说明、外尺寸准确双单位文字、箭头位置、完整单图任务词、检查项。</span></span>
<span class="line"><span>换算是数学处理，不等于重新测量；没有品牌尺码表时，不推导服装S/M/L或鞋码。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const h=a(l,[["render",t]]);export{_ as __pageData,h as default};
